mapper.select:
SELECT 
FROM calendar
WHERE deleted = false

    AND name ILIKE CONCAT('%', #{name}, '%')


    AND type = #{type}


    AND resource_id = #{resourceId,typeHandler=org.apache.ibatis.type.ObjectTypeHandler}


    AND resource_group_id = #{resourceGroupId,typeHandler=org.apache.ibatis.type.ObjectTypeHandler}

ORDER BY effective_from DESC, name ASC

SELECT COUNT(*)
FROM calendar
WHERE deleted = false
  AND name = #{name}
  AND calendar_version = #{calendarVersion}

    AND id <> #{excludeId,typeHandler=org.apache.ibatis.type.ObjectTypeHandler}

mapper.update:
UPDATE calendar
SET deleted = true,
    version = version + 1,
    updated_at = #{updatedAt},
    updated_by = #{updatedBy,typeHandler=org.apache.ibatis.type.ObjectTypeHandler}
WHERE id = #{id,typeHandler=org.apache.ibatis.type.ObjectTypeHandler}
  AND version = #{version}
  AND deleted = false
